-- Application keys are generated by the Edge Function, never stored in the frontend.
begin;
create table public.push_server_config (
  id boolean primary key default true check (id),
  public_key text not null,
  private_key text not null,
  cron_secret text not null,
  created_at timestamptz not null default now()
);
alter table public.push_server_config enable row level security;
revoke all on public.push_server_config from anon, authenticated;
grant select, insert on public.push_server_config to service_role;
commit;

-- The endpoint is deployed with verify_jwt=false and authenticates POST using its own secret.
create extension if not exists pg_cron;
create extension if not exists pg_net with schema extensions;
select cron.schedule('medcontrol-reminders', '* * * * *', $$
  select net.http_post(
    url := 'https://pvadfgerkkvlecwfhiuq.supabase.co/functions/v1/dispatch-reminders',
    headers := jsonb_build_object('Content-Type', 'application/json', 'Authorization', 'Bearer ' || (select cron_secret from public.push_server_config where id = true)),
    body := '{}'::jsonb,
    timeout_milliseconds := 55000
  ) where exists (select 1 from public.push_server_config where id = true);
$$);
